using System;using System.IO;using System.Drawing;using System.Windows.Forms;
namespace FleetLab
{
    internal static class PracticeReinforcementClockFormChecks
    {
        static T C<T>(Form f,string n)where T:Control{return(T)f.Controls.Find(n,true)[0];}static void Need(bool v,string m){if(!v)throw new Exception(m);}static void Click(Form f,string n){C<Button>(f,n).PerformClick();Application.DoEvents();}static void Show(Form f,Form owner){f.Show(owner);Application.DoEvents();}
        internal static void Run(Action<string,Action> check,string assets,Form owner)
        {
            string programs=Path.Combine(Path.GetDirectoryName(assets),"Programs");
            check("Clock-wave window exposes separate mode and body versus completed clock fields",delegate{using(var parent=new PracticeGeneratedReinforcementStudy(programs))using(var f=new PracticeReinforcementPhaseStudy(programs,true)){Need(parent.Controls.Find("generatedClockWaves",true).Length==1,"Discoverable clock mode entry");Show(f,owner);Need(C<ComboBox>(f,"phaseWavePause").Items.Count==2&&f.ClockSnapshot.Clock.DeltaMilliseconds==13,"Compared pause choices/initialdelta");Click(f,"phaseWaveStep");Need(f.ClockSnapshot.Frames==1&&f.ShownClockUpdate.BodyClock.DeltaMilliseconds==13&&C<TextBox>(f,"phaseWaveDetails").Text.Contains("OLD delta 13"),"Body olddelta feedback");}});
            check("Clock-wave window inspects zero-interval eight-fleet burst without rewinding current frame",delegate{using(var f=new PracticeReinforcementPhaseStudy(programs,true)){Show(f,owner);C<ComboBox>(f,"phaseWavePause").SelectedIndex=1;Click(f,"phaseWaveLoad");Click(f,"phaseWaveFinish");Need(f.ClockSnapshot.Frames==96&&f.StateSnapshot.World.CreatedFleetCount==8,"Finite trace complete");C<DataGridView>(f,"phaseWaveTrace").CurrentCell=C<DataGridView>(f,"phaseWaveTrace").Rows[66].Cells[0];Application.DoEvents();Need(f.ShownSnapshot.Frames==67&&f.ShownClockUpdate.ZeroInterval&&f.ShownSnapshot.World.LastCreated.Count==8&&f.ShownClockUpdate.State.Clock.GameMilliseconds==1&&f.ClockSnapshot.Frames==96,"Historical zero-frame/epilogue selection");Need(C<TextBox>(f,"phaseWaveDetails").Text.Contains("epilogue resets to1"),"Explicit zero correction feedback");C<DataGridView>(f,"phaseWaveTrace").CurrentCell=C<DataGridView>(f,"phaseWaveTrace").Rows[31].Cells[0];Application.DoEvents();Need(f.ShownSnapshot.Frames==32&&f.ShownSnapshot.World.CreatedFleetCount==0&&f.StateSnapshot.Frames==96,"Historical equality before birth");}});
            check("Clock-wave window applies phase31 and MAX choices while preserving pending reset and Enter edges",delegate{using(var f=new PracticeReinforcementPhaseStudy(programs,true)){Show(f,owner);C<ComboBox>(f,"phaseWaveInitial").SelectedIndex=1;Click(f,"phaseWaveLoad");Click(f,"phaseWaveStep");Need(f.StateSnapshot.PhaseCounter==32&&f.StateSnapshot.World.CreatedFleetCount==1,"First supplied sample overdue");C<ComboBox>(f,"phaseWaveInitial").SelectedIndex=2;Click(f,"phaseWaveReset");Need(f.StateSnapshot.InitialPhase==31&&f.ClockSnapshot.Frames==0&&C<Label>(f,"phaseWavePending").Text.Contains("pending"),"Reset preserves applied phase31");f.StudyKey(Keys.Enter,false);f.StudyKey(Keys.Enter,true);Click(f,"phaseWaveStep");Need(f.StateSnapshot.PhaseCounter==0&&f.StateSnapshot.World.CreatedFleetCount==0,"MAX wraps belowdeadline");C<ComboBox>(f,"phaseWaveSeed").SelectedIndex=1;f.StudyKey(Keys.Enter,true);Need(f.StateSnapshot.World.InitialSeed==731,"HeldEnter suppressed");f.StudyKey(Keys.Enter,false);f.StudyKey(Keys.Enter,true);f.StudyKey(Keys.Enter,false);Need(f.StateSnapshot.World.InitialSeed==0,"Nextpress applies seed0");}});
            check("Clock-wave minimum scrolling preserves fixed Close and closes populated history cleanly",delegate{using(var f=new PracticeReinforcementPhaseStudy(programs,true)){Show(f,owner);Click(f,"phaseWaveFinish");f.ClientSize=new Size(940,620);var d=C<TextBox>(f,"phaseWaveDetails");d.Focus();C<Panel>(f,"phaseWaveScroll").ScrollControlIntoView(d);Application.DoEvents();var close=C<Button>(f,"phaseWaveClose");Need(d.Width>=860&&f.ClientRectangle.Contains(new Rectangle(f.PointToClient(close.PointToScreen(Point.Empty)),close.Size)),"Readable scrollable details andfixedClose");Click(f,"phaseWaveClose");Need(f.IsDisposed||!f.Visible,"Clean close withhistorical callbacks");}});
        }
        static void Save(Form f,string output,string name){Application.DoEvents();using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,f.Size));b.Save(Path.Combine(output,name+".png"),System.Drawing.Imaging.ImageFormat.Png);}}
        internal static int SavePreviews(string assets,string output)
        {
            try{Directory.CreateDirectory(output);using(var f=new PracticeReinforcementPhaseStudy(Path.Combine(Path.GetDirectoryName(assets),"Programs"),true)){f.ShowInTaskbar=false;f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.Show();Application.DoEvents();Save(f,output,"01-initial");Click(f,"phaseWave32");Save(f,output,"02-equality32");Click(f,"phaseWave32");Save(f,output,"03-one-fleet64");C<ComboBox>(f,"phaseWaveInitial").SelectedIndex=1;Click(f,"phaseWaveLoad");Click(f,"phaseWaveStep");Save(f,output,"04-first-frame-overdue");C<ComboBox>(f,"phaseWaveInitial").SelectedIndex=0;C<ComboBox>(f,"phaseWavePause").SelectedIndex=1;Click(f,"phaseWaveLoad");Click(f,"phaseWaveFinish");C<DataGridView>(f,"phaseWaveTrace").CurrentCell=C<DataGridView>(f,"phaseWaveTrace").Rows[66].Cells[0];Application.DoEvents();Save(f,output,"05-zero-interval-burst");f.ClientSize=new Size(940,620);var d=C<TextBox>(f,"phaseWaveDetails");d.Focus();C<Panel>(f,"phaseWaveScroll").ScrollControlIntoView(d);Save(f,output,"06-minimum-details");var g=C<DataGridView>(f,"phaseWaveTrace");g.Focus();C<Panel>(f,"phaseWaveScroll").ScrollControlIntoView(g);Save(f,output,"07-minimum-trace");f.Close();}return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(output,"Error.txt"),ex.ToString());return 1;}
        }
    }
}
